<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Services\AuditService;use App\Support\LegacyResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Throwable;
class BreakdownController extends Controller
{
 public function __construct(private AuditService $audit){} private function user(Request $r){return $r->attributes->get('jwt_user');}
 public function index(Request $r){$q=DB::table('breakdowns as b')->join('equipment as e','b.equipment_id','=','e.id')->leftJoin('stop_reasons as sr','b.initial_reason_id','=','sr.id')->leftJoin('users as u','b.closed_by','=','u.id')->select('b.*','e.name as equipment_name','e.code as equipment_code','e.department','e.location','e.plant as equipment_plant','sr.description as initial_reason','sr.category as reason_category','u.full_name as closed_by_name',DB::raw('ROUND(TIMESTAMPDIFF(SECOND,b.start_time,COALESCE(b.end_time,NOW()))/60) AS runtime_downtime_min'));if($r->filled('status'))$q->where('b.status',$r->input('status'));if($r->filled('equipment_id'))$q->where('b.equipment_id',$r->input('equipment_id'));if($r->filled('from_date'))$q->whereDate('b.start_time','>=',$r->input('from_date'));if($r->filled('to_date'))$q->whereDate('b.start_time','<=',$r->input('to_date'));if($r->filled('department'))$q->where('e.department',$r->input('department'));if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));return response()->json(['success'=>true,'data'=>$q->orderByDesc('b.start_time')->limit(500)->get()->map(fn($x)=>LegacyResponse::normalize($x))->all()]);}
 public function open(Request $r){try{$q=DB::table('v_open_breakdowns as v');if($r->filled('plant'))$q->join('equipment as e','e.id','=','v.equipment_id')->where('e.plant',$r->input('plant'))->select('v.*');return response()->json(['success'=>true,'data'=>$q->orderBy('v.start_time')->get()->map(fn($x)=>LegacyResponse::normalize($x))->all()]);}catch(Throwable $e){return response()->json(['success'=>false,'message'=>$e->getMessage()],500);}}
 public function show($id){$x=DB::table('breakdowns as b')->join('equipment as e','b.equipment_id','=','e.id')->leftJoin('stop_reasons as sr','b.initial_reason_id','=','sr.id')->leftJoin('users as u','b.closed_by','=','u.id')->leftJoin('shift_logs as sl','b.shift_log_id','=','sl.id')->leftJoin('users as su','sl.operator_id','=','su.id')->select('b.*','e.name as equipment_name','e.code as equipment_code','e.department','e.location','sr.description as initial_reason','sr.category as reason_category','u.full_name as closed_by_name','su.full_name as reported_by','sl.shift as reported_shift')->where('b.id',$id)->first();if(!$x)return response()->json(['success'=>false,'message'=>'Not found'],404);return response()->json(['success'=>true,'data'=>LegacyResponse::normalize($x)]);}
 public function update(Request $r,$id){try{$exists=DB::table('breakdowns')->where('id',$id)->where('status','OPEN')->exists();if(!$exists)return response()->json(['success'=>false,'message'=>'Breakdown not found or already closed'],404);DB::table('breakdowns')->where('id',$id)->update(['findings'=>$r->input('findings'),'actions_taken'=>$r->input('actions_taken'),'spares_used'=>$r->input('spares_used'),'resolution_notes'=>$r->input('resolution_notes'),'updated_at'=>now()]);$row=DB::table('breakdowns')->where('id',$id)->first();$this->audit->log($this->user($r)->id,'UPDATE_BREAKDOWN','breakdowns',$id,$r->all(),$r->ip());return response()->json(['success'=>true,'data'=>LegacyResponse::normalize($row)]);}catch(Throwable $e){return response()->json(['success'=>false,'message'=>$e->getMessage()],500);}}
 public function close(Request $r,$id){if(!$r->input('resolution_notes'))return response()->json(['success'=>false,'message'=>'Resolution notes required to close'],400);try{$closed=DB::transaction(function()use($r,$id){$bd=DB::table('breakdowns')->where('id',$id)->where('status','OPEN')->lockForUpdate()->first();if(!$bd)return null;$down=round((time()-strtotime($bd->start_time))/60,2);DB::table('breakdowns')->where('id',$id)->update(['status'=>'CLOSED','end_time'=>now(),'downtime_minutes'=>$down,'findings'=>$r->input('findings'),'actions_taken'=>$r->input('actions_taken'),'spares_used'=>$r->input('spares_used'),'resolution_notes'=>$r->input('resolution_notes'),'closed_by'=>$this->user($r)->id,'closed_at'=>now(),'updated_at'=>now()]);DB::table('equipment')->where('id',$bd->equipment_id)->update(['current_status'=>'RUNNING','updated_at'=>now()]);return DB::table('breakdowns')->where('id',$id)->first();});if(!$closed)return response()->json(['success'=>false,'message'=>'Open breakdown not found'],404);$this->audit->log($this->user($r)->id,'CLOSE_BREAKDOWN','breakdowns',$id,['downtime_minutes'=>$closed->downtime_minutes],$r->ip());return response()->json(['success'=>true,'message'=>"Breakdown closed. Downtime: {$closed->downtime_minutes} minutes.",'data'=>LegacyResponse::normalize($closed)]);}catch(Throwable $e){return response()->json(['success'=>false,'message'=>$e->getMessage()],500);}}
}
